contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 1 ether);

        vm.prank(user);
        c.addToBalance{value: 1 ether}();

        uint256 balanceBefore = c.getBalance(user);

        vm.prank(user);
        c.withdrawBalance();

        uint256 balanceAfter = c.getBalance(user);



        assertTrue(address(user).balance > 0, "User should have received ether");
    }
}
